#[test]
fn long_mode2_base() {
    for (i, w) in CURVES0.iter().enumerate() { assert_eq!(curves(2)[0][i], *w, "c0 {i}"); }
    for (i, w) in CURVES1.iter().enumerate() { assert_eq!(curves(2)[1][i], *w, "c1 {i}"); }
    for (i, w) in CURVES2.iter().enumerate() { assert_eq!(curves(2)[2][i], *w, "c2 {i}"); }
    let f = field_19(2);
    for (i, w) in FIELD19.iter().enumerate() { assert_eq!(f[i], *w, "f19 {i}"); }
    let iv = interval(2);
    for (i, w) in INTERVAL.iter().enumerate() { assert_eq!(iv[i], *w, "iv {i}"); }
}

#[test]
fn long_mode3_variants() {
    let c = curves(3);
    for (i, w) in V3_CURVES.iter().enumerate() {
        assert_eq!(c[i / 1024][i % 1024], *w, "v3c {i}");
    }
    let f = field_19(3);
    for (i, w) in V3_FIELD19.iter().enumerate() { assert_eq!(f[i], *w, "v3f {i}"); }
    let iv = interval(3);
    for (i, w) in V3_INTERVAL.iter().enumerate() { assert_eq!(iv[i], *w, "v3iv {i}"); }
}

#[test]
fn long_seed_pair() {
    let b = base_curve();
    for (i, w) in BASE_CURVE.iter().enumerate() { assert_eq!(b[i], *w, "bc {i}"); }
    let g = group_labels();
    for (i, w) in GROUP_LABELS.iter().enumerate() { assert_eq!(g[i], *w, "gl {i}"); }
}

